//! Windows only: embeds the application icon and file version information in
//! crane.exe, so Explorer, the installer, shortcuts and Apps & features show the
//! logo (issue #20). The icon is generated by scripts/gen-icons.ps1.
//!
//! `winresource` is a Windows-host build dependency, so this only runs on
//! native Windows builds (which is how CI and scripts/build.ps1 build crane.exe).

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=../packaging/crane.ico");
    #[cfg(windows)]
    embed_windows_resources();
}

#[cfg(windows)]
fn embed_windows_resources() {
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let mut res = winresource::WindowsResource::new();
    res.set_icon("../packaging/crane.ico")
        .set("ProductName", "Crane Camera Automated Navigation Hub")
        .set("FileDescription", "Crane Camera Automated Navigation Hub")
        .set("CompanyName", "Optitrion")
        .set("LegalCopyright", "© 2026 Optitrion")
        .set("InternalName", "crane")
        .set("OriginalFilename", "crane.exe");
    if let Err(e) = res.compile() {
        // A build without the icon still works; make the reason visible, and
        // fail in CI so a release never silently loses it.
        println!("cargo:warning=could not embed the Windows icon: {e}");
        assert!(
            std::env::var_os("CI").is_none(),
            "embedding the Windows icon failed in CI: {e}"
        );
    }
}
